import { api, tags, urlUtils } from '@igblsln/store';
const API_PATH = '/project/work/';
export const WorkInfoApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listWorkDetails: build.query({
            query: ({ project, block, category, type }) => {
                return {
                    url: urlUtils(API_PATH, `?project=${project}&block=${block}&category=${category}&type=${type}&without_pagination=1`),
                };
            },
            providesTags: (result) => (result === null || result === void 0 ? void 0 : result.results)
                ? [
                    ...result.results.map(({ key }) => ({
                        type: "WORK_DETAILS",
                        id: key,
                    })),
                    { type: "WORK_DETAILS", id: "LIST" },
                ]
                : [{ type: "WORK_DETAILS", id: "LIST" }],
        }),
        getWorkNameCategory: build.query({
            query: () => ({
                url: urlUtils('/estimate/category/'),
            }),
            providesTags: (result) => result ? [{ type: tags.WORK_INFO, id: 'LIST' }] : [{ type: tags.WORK_INFO, id: 'LIST' }],
        }),
        listWorkNameCategory: build.query({
            query: () => ({
                url: urlUtils('/estimate/category/?without_pagination=1'),
            }),
            providesTags: (result) => result ? [{ type: tags.WORK_INFO, id: 'LIST' }] : [{ type: tags.WORK_INFO, id: 'LIST' }],
        }),
        getWorkNameTypeByCategory: build.query({
            query: (type) => ({
                url: urlUtils('/estimate/type/', `?${type ? `&category=${type}` : ''}&without_pagination=1`),
            }),
            providesTags: (result) => result ? [{ type: tags.WORK_INFO, id: 'LIST' }] : [{ type: tags.WORK_INFO, id: 'LIST' }],
        }),
        getErrorProne: build.query({
            query: () => 'error-prone',
        }),
    }),
});
export const { useGetErrorProneQuery, useGetWorkNameCategoryQuery, useGetWorkNameTypeByCategoryQuery, useListWorkDetailsQuery, useListWorkNameCategoryQuery } = WorkInfoApi;
